pub(crate) struct Oracle {
    pub meta: Vec<(String, Value)>,
    pub cases: Vec<(String, Value)>,
}

impl Oracle {
    pub(crate) fn meta(&self, id: &str) -> Result<&Value, String> {
        match self.meta.iter().find(|(k, _)| k.as_str() == id) {
            Some((_, v)) => Ok(v),
            None => Err(format!("no meta row {}", id)),
        }
    }

    pub(crate) fn case(&self, id: &str) -> Result<&Value, String> {
        match self.cases.iter().find(|(k, _)| k.as_str() == id) {
            Some((_, v)) => Ok(v),
            None => Err(format!("no case row {}", id)),
        }
    }
}

/// Splits the text into `sd1 <meta|case> <id> <value>` rows and parses every value. The file must end with
/// exactly one newline and hold no blank row.
pub(crate) fn parse_oracle(text: &str) -> Result<Oracle, String> {
    if !text.ends_with('\n') {
        return Err("oracle must end with a newline".to_string());
    }
    let mut oracle = Oracle {
        meta: Vec::new(),
        cases: Vec::new(),
    };
    for (n, line) in text[..text.len() - 1].split('\n').enumerate() {
        let mut f = line.splitn(4, ' ');
        let (tag, kind, id, payload) = match (f.next(), f.next(), f.next(), f.next()) {
            (Some(a), Some(b), Some(c), Some(d)) => (a, b, c, d),
            _ => return Err(format!("row {} has fewer than four fields", n + 1)),
        };
        if tag != "sd1" {
            return Err(format!("row {} has tag {:?}, expected sd1", n + 1, tag));
        }
        let v =
            parse_value(payload).map_err(|e| format!("row {} ({} {}): {}", n + 1, kind, id, e))?;
        match kind {
            "meta" => oracle.meta.push((id.to_string(), v)),
            "case" => oracle.cases.push((id.to_string(), v)),
            other => return Err(format!("row {} has unknown kind {:?}", n + 1, other)),
        }
    }
    Ok(oracle)
}

fn names(v: &Value) -> Vec<String> {
    v.items()
        .iter()
        .map(|x| x.as_str().unwrap_or("<non-string>").to_string())
        .collect()
}

fn expect_list(what: &str, got: &[String], want: &[&str]) -> Result<(), String> {
    let want: Vec<String> = want.iter().map(|s| s.to_string()).collect();
    if got == want.as_slice() {
        Ok(())
    } else {
        Err(format!("{}: got {:?}, want {:?}", what, got, want))
    }
}

/// Completeness and shape: the meta rows, the case ids and order, the members of every case, the baseline
/// provenance (commit, anchors, slice hashes), the `serP` key list, and the rule that an output only holds keys
/// `serP` can return, in `serP` order.
pub(crate) fn check_structure(o: &Oracle) -> Result<(), String> {
    let meta_ids: Vec<String> = o.meta.iter().map(|(k, _)| k.clone()).collect();
    expect_list("meta ids", &meta_ids, META_IDS)?;
    let case_ids: Vec<String> = o.cases.iter().map(|(k, _)| k.clone()).collect();
    expect_list("case ids", &case_ids, CASE_IDS)?;
    if o.meta("commit")?.as_str() != Some(COMMIT) {
        return Err("commit meta row is not the baseline commit".to_string());
    }
    let serp: Vec<String> = SERP_KEYS.split(',').map(|s| s.to_string()).collect();
    let got_keys = names(o.meta("serp-keys")?);
    if got_keys != serp {
        return Err(format!(
            "serp-keys differ from the pinned 81: {:?}",
            got_keys
        ));
    }
    expect_list(
        "pressure keys",
        &names(o.meta("pressure-keys")?),
        &["bitmapPressureProfile"],
    )?;
    for (name, line) in ANCHOR_LINES {
        let got = o.meta("anchor-lines")?.get(name).as_f64();
        if got != Some(*line) {
            return Err(format!(
                "anchor line of {}: got {:?}, want {}",
                name, got, line
            ));
        }
    }
    for (name, sha) in SLICE_SHA256 {
        if o.meta("slice-sha256")?.get(name).as_str() != Some(*sha) {
            return Err(format!("slice hash of {} differs", name));
        }
    }
    for (id, case) in &o.cases {
        if case.keys() != CASE_KEYS {
            return Err(format!("case {}: members {:?}", id, case.keys()));
        }
        for part in ["in", "paper", "out", "out2"] {
            if !case.get(part).is_obj() {
                return Err(format!("case {}: {} is not an object", id, part));
            }
        }
        if case.get("paper").keys() != PAPER_KEYS {
            return Err(format!(
                "case {}: paper members {:?}",
                id,
                case.get("paper").keys()
            ));
        }
        for part in ["out", "out2"] {
            let mut last = 0usize;
            for key in case.get(part).keys() {
                match serp[last..].iter().position(|k| k == key) {
                    Some(at) => last += at + 1,
                    None => {
                        return Err(format!(
                            "case {}: {} has key {:?} outside serP's order",
                            id, part, key
                        ))
                    }
                }
            }
            if case.get(part).get("segments").is_undef() {
                return Err(format!("case {}: {} lacks segments", id, part));
            }
        }
    }
    Ok(())
}

pub(crate) fn load() -> Oracle {
    match parse_oracle(ORACLE) {
        Ok(o) => o,
        Err(e) => panic!("oracle does not parse: {}", e),
    }
}

#[test]
fn oracle_is_complete_and_well_formed() {
    let o = load();
    assert_eq!(o.meta.len(), 5);
    assert_eq!(o.cases.len(), 60);
    assert_eq!(ORACLE.lines().count(), 65);
    check_structure(&o).expect("structure");
}

#[test]
fn serp_key_set_has_no_pathfx_and_no_pressure_scalar() {
    let o = load();
    let keys = names(o.meta("serp-keys").expect("meta"));
    assert_eq!(keys.len(), 81);
    // pathFx is a layer field (ld.pathFx), never a stroke member
    assert!(!keys.iter().any(|k| k.to_lowercase().contains("pathfx")));
    // the only pressure-named member is the bitmap-brush profile, which belongs to lane 7
    let pressure: Vec<&str> = keys
        .iter()
        .map(|k| k.as_str())
        .filter(|k| k.to_lowercase().contains("pressure"))
        .collect();
    assert_eq!(pressure, vec!["bitmapPressureProfile"]);
    // the four pressure-ribbon members of this lane
    for k in [
        "centerSegments",
        "widthProfile",
        "strokeProfile",
        "profileBase",
        "isVectorBrush",
        "isFillShape",
    ] {
        assert!(keys.iter().any(|x| x.as_str() == k), "{} missing", k);
    }
}

#[test]
fn baseline_provenance_is_the_pinned_commit() {
    let o = load();
    assert_eq!(o.meta("commit").expect("meta").as_str(), Some(COMMIT));
    let anchors = o.meta("anchor-lines").expect("meta");
    assert_eq!(anchors.get("serP").as_f64(), Some(609.0));
    assert_eq!(anchors.get("desP").as_f64(), Some(846.0));
    assert_eq!(anchors.get("_r3").as_f64(), Some(608.0));
    assert_eq!(anchors.get("pathFxActiveStack").as_f64(), Some(185.0));
}
